mapper.update:
UPDATE calendar_tbl
   SET subject    = #{event.subject},
       content    = #{event.content},
       started_at = #{event.start},
       ended_at   = #{event.end},
       type       = #{event.type}
 WHERE id = #{event.id}
   AND user_tbl_id = #{event.userId}

mapper.delete:
DELETE FROM calendar_tbl
      WHERE id = #{id}
        AND user_tbl_id = #{userId}
